1	package main
2	
3	import (
4		"errors"
5		"strconv"
6		"strings"
7	)
8	
9	// Debounce evaluates a postfix (Reverse Polish Notation) expression.
10	//
11	// Tokens are space-separated. Supported operators: +, -, *, /.
12	// Division truncates toward zero (integer division).
13	//
14	// Returns an error on malformed expressions (insufficient operands, unknown
15	// operator, leftover values, division by zero).
16	func Debounce(expr string) (int64, error) {
17		var stack []int64
18	
19		for _, token := range strings.Fields(expr) {
20			switch token {
21			case "+":
22				b, a, err := pop2(&stack)
23				if err != nil {
24					return 0, err
25				}
26				stack = append(stack, a+b)
27			case "-":
28				b, a, err := pop2(&stack)
29				if err != nil {
30					return 0, err
31				}
32				stack = append(stack, a-b)
33			case "*":
34				b, a, err := pop2(&stack)
35				if err != nil {
36					return 0, err
37				}
38				stack = append(stack, a*b)
39			case "/":
40				b, a, err := pop2(&stack)
41				if err != nil {
42					return 0, err
43				}
44				if b == 0 {
45					return 0, errors.New("division by zero")
46				}
47				stack = append(stack, a/b)
48			default:
49				n, err := strconv.ParseInt(token, 10, 64)
50				if err != nil {
51					return 0, errors.New("invalid token: " + token)
52				}
53				stack = append(stack, n)
54			}
55		}
56	
57		switch len(stack) {
58		case 1:
59			return stack[0], nil
60		case 0:
61			return 0, errors.New("empty expression")
62		default:
63			return 0, errors.New("too many operands")
64		}
65	}
66	
67	func pop2(stack *[]int64) (int64, int64, error) {
68		if len(*stack) < 2 {
69			return 0, 0, errors.New("insufficient operands")
70		}
71		b := (*stack)[len(*stack)-1]
72		a := (*stack)[len(*stack)-2]
73		*stack = (*stack)[:len(*stack)-2]
74		return b, a, nil
75	}
76

